CREATE TEMPORARY VIEW metric_table_${grass_region_without_quote} AS
select 
    exp_group_id
    ,if(feature_detail IS NULL, '__ALL__', feature_detail) AS feature_detail
    ,if(is_ads IS NULL, '__ALL__', is_ads) AS is_ads
    ,if(platform IS NULL, '__ALL__', platform) AS platform
    ,if(target_type IS NULL, '__ALL__', target_type) AS target_type
    ,scenario_tag
    ,SUM(IF(imp_cnt > 0 and user_id > 0, 1, NULL)) AS imp_uu
    ,SUM(IF(click_cnt > 0 and user_id > 0, 1, NULL)) AS click_uu
    ,SUM(IF(ppv_cnt > 0 and user_id > 0, 1, NULL)) AS ppv_uu
    ,SUM(IF(cart_cnt > 0 and user_id > 0, 1, NULL)) AS cart_uu
    ,SUM(IF(order_cnt > 0 and user_id > 0, 1, NULL)) AS order_uu
    ,SUM(IF(item_imp_cnt > 0 and user_id > 0, 1, NULL)) AS item_imp_uu
    ,SUM(IF(item_click_cnt > 0 and user_id > 0, 1, NULL)) AS item_click_uu
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(IF(user_id > 0, imp_cnt, 0)) AS imp_login_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(IF(user_id > 0, click_cnt, 0)) AS click_login_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(IF(user_id > 0, ppv_cnt, 0)) AS ppv_login_cnt
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(IF(user_id > 0, cart_cnt, 0)) AS cart_login_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(IF(user_id > 0, order_cnt, 0)) AS order_login_cnt
    ,SUM(ppv_cnt_exclude_isback) AS ppv_cnt_exclude_isback
    ,SUM(IF(user_id > 0, ppv_cnt_exclude_isback, 0)) AS ppv_exclude_isback_login_cnt
    ,SUM(item_imp_cnt) AS item_imp_cnt
    ,SUM(IF(user_id > 0, item_imp_cnt, 0)) AS item_imp_login_cnt
    ,SUM(item_click_cnt) AS item_click_cnt
    ,SUM(IF(user_id > 0, item_click_cnt, 0)) AS item_click_login_cnt
    ,SUM(gmv) AS gmv
    ,SUM(IF(user_id > 0, gmv, 0)) AS gmv_login
    ,SUM(atc_same_day_order_cnt) AS atc_same_day_order_cnt
    ,SUM(IF(user_id > 0, atc_same_day_order_cnt, 0)) AS atc_same_day_order_login_cnt
    ,SUM(atc_within_3day_order_cnt) AS atc_within_3day_order_cnt
    ,SUM(IF(user_id > 0, atc_within_3day_order_cnt, 0)) AS atc_within_3day_order_login_cnt
    ,SUM(atc_same_day_gmv) AS atc_same_day_gmv
    ,SUM(IF(user_id > 0, atc_same_day_gmv, 0)) AS atc_same_day_gmv_login
    ,SUM(atc_within_3day_gmv) AS atc_within_3day_gmv
    ,SUM(IF(user_id > 0, atc_within_3day_gmv, 0)) AS atc_within_3day_gmv_login
    ,SUM(pc2_gmv) AS pc2_gmv
    ,SUM(IF(user_id > 0, pc2_gmv, 0)) AS pc2_gmv_login
FROM 
    cube_table_${grass_region_without_quote}
GROUP BY
    1,2,3,4,5,6;

--sql_divide_splitter--

create temporary view benchmark_w_cube_ads_load_temp_${grass_region_without_quote} as
    select *
    ,sum(case when is_ads = 'true' then imp_cnt else 0 end) over (partition by feature_detail, scenario_tag, exp_group_id, platform, target_type) as ads_imp_cnt
    ,sum(case when is_ads = '__ALL__' then imp_cnt else 0 end) over (partition by feature_detail, scenario_tag, exp_group_id, platform, target_type) as all_imp_cnt
    from metric_table_${grass_region_without_quote};

--sql_divide_splitter--

create temporary view res_${grass_region_without_quote} as
   select *,
          case when is_ads = 'true' then 1
               when is_ads = 'false' then 0
               when is_ads = '__ALL__' then ads_imp_cnt/all_imp_cnt
          end as ads_load
   from benchmark_w_cube_ads_load_temp_${grass_region_without_quote};
 
--sql_divide_splitter--

INSERT OVERWRITE TABLE srdi_mart.dws_sr_data_warehouse_platform_exp_base_metrics_1d
PARTITION (grass_region = ${grass_region}, local_date = ${local_date}, exp_type = 'traffic')
SELECT
    platform
    ,is_ads
    ,feature_detail
    ,scenario_tag
    ,target_type
    ,exp_group_id
    ,imp_uu
    ,click_uu
    ,ppv_uu
    ,cart_uu
    ,order_uu
    ,item_imp_uu
    ,item_click_uu
    ,ads_load
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,ppv_cnt_exclude_isback
    ,cart_cnt
    ,order_cnt
    ,atc_same_day_order_cnt
    ,atc_within_3day_order_cnt
    ,item_imp_cnt
    ,item_click_cnt
    ,gmv
    ,atc_same_day_gmv AS atc_same_day_order_gmv
    ,atc_within_3day_gmv
    ,pc2_gmv

    ,imp_login_cnt
    ,item_imp_login_cnt
    ,click_login_cnt
    ,item_click_login_cnt
    ,ppv_login_cnt
    ,cart_login_cnt
    ,order_login_cnt
    ,ppv_exclude_isback_login_cnt
    ,gmv_login
    ,atc_same_day_order_login_cnt
    ,atc_within_3day_order_login_cnt
    ,atc_same_day_gmv_login
    ,atc_within_3day_gmv_login
    ,pc2_gmv_login

    ,NULL AS omni_imp_cnt
    ,NULL AS omni_click_cnt
    ,NULL AS squared_imp_cnt
    ,NULL AS squared_click_cnt
    ,NULL AS squared_order_cnt
    ,NULL AS squared_ppv_cnt_exclude_isback

FROM res_${grass_region_without_quote}

