CACHE TABLE base_table_${grass_region_without_quote}  OPTIONS('storageLevel'='DISK_ONLY') AS
SELECT
    coalesce(platform, 'NULL') AS platform
    ,user_id
    ,feature_detail
    ,source1_feature_detail
    ,source2_feature_detail
    ,FILTER(scenario_tags, value -> value not like 'Page%' and value not like '%mapping group%') as scenario_tags
    ,FILTER(source1_scenario_tags, value -> value not like 'Page%' and value not like '%mapping group%') as source1_scenario_tags
    ,FILTER(source2_scenario_tags, value -> value not like 'Page%' and value not like '%mapping group%') as source2_scenario_tags
    ,cast(coalesce(is_ads, false) as string)   as is_ads
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(omni_imp_cnt) AS omni_imp_cnt
    ,SUM(omni_click_cnt) AS omni_click_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(if(is_back, 0, ppv_cnt)) AS ppv_cnt_exclude_isback
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(if(imp_cnt>0 AND if(split(feature_detail, '-')[2] IS NOT NULL, split(feature_detail, '-')[2], split(feature_detail, '-')[1])='item', imp_cnt, 0)) AS item_imp_cnt
    ,SUM(if(click_cnt>0 AND if(split(feature_detail, '-')[2] IS NOT NULL, split(feature_detail, '-')[2], split(feature_detail, '-')[1])='item', click_cnt, 0)) AS item_click_cnt
    ,SUM(gmv) AS gmv
    ,SUM(atc_same_day_order_cnt) AS atc_same_day_order_cnt
    ,SUM(atc_within_3day_order_cnt) AS atc_within_3day_order_cnt
    ,SUM(atc_same_day_gmv) AS atc_same_day_gmv
    ,SUM(atc_within_3day_gmv) AS atc_within_3day_gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM srdi_mart.dwm_sr_data_warehouse_platform_user_item
WHERE grass_region = ${grass_region} AND local_date = ${local_date}
    AND operation IN ('impression', 'click', 'ppv', 'cart', 'order', 'omni_impression', 'omni_click')
    AND user_id > 0
GROUP BY
    1,2,3,4,5,6,7,8,9;

--sql_divide_splitter--

