CREATE TEMPORARY VIEW squared_data_${grass_region_without_quote} AS
SELECT
    *
    ,IF(imp_cnt > 0 and user_id > 0, 1, 0) AS imp_uu
    ,IF(click_cnt > 0 and user_id > 0, 1, 0) AS click_uu
    ,IF(ppv_cnt > 0 and user_id > 0, 1, 0) AS ppv_uu
    ,IF(cart_cnt > 0 and user_id > 0, 1, 0) AS cart_uu
    ,IF(order_cnt > 0 and user_id > 0, 1, 0) AS order_uu
    ,IF(item_imp_cnt > 0 and user_id > 0, 1, 0) AS item_imp_uu
    ,IF(item_click_cnt > 0 and user_id > 0, 1, 0) AS item_click_uu
    ,power(imp_cnt,2) AS squared_imp_cnt
    ,power(click_cnt,2) AS squared_click_cnt
    ,power(order_cnt,2) AS squared_order_cnt
    ,power(ppv_cnt_exclude_isback,2) AS squared_ppv_cnt_exclude_isback
FROM
    cube_table_${grass_region_without_quote};

--sql_divide_splitter--
create TEMPORARY VIEW map_data_${grass_region_without_quote} as
select
    feature_detail
     ,is_ads
     ,platform
     ,target_type
     ,user_id
     ,scenario_tag
     ,array(
        imp_uu
        ,click_uu
        ,ppv_uu
        ,cart_uu
        ,order_uu
        ,item_imp_uu
        ,item_click_uu
        ,imp_cnt
        ,click_cnt
        ,ppv_cnt
        ,cart_cnt
        ,order_cnt
        ,ppv_cnt_exclude_isback
        ,item_imp_cnt
        ,item_click_cnt
        ,gmv
        ,atc_same_day_order_cnt
        ,atc_within_3day_order_cnt
        ,atc_same_day_gmv
        ,atc_within_3day_gmv
        ,pc2_gmv
        ,omni_imp_cnt
        ,omni_click_cnt
        ,squared_imp_cnt
        ,squared_click_cnt
        ,squared_order_cnt
        ,squared_ppv_cnt_exclude_isback
      ) as metrics
from
    squared_data_${grass_region_without_quote};

--sql_divide_splitter--

CREATE TEMPORARY VIEW explode_metric_table_${grass_region_without_quote} AS
SELECT
    if(feature_detail IS NULL, '__ALL__', feature_detail) AS feature_detail
    ,if(is_ads IS NULL, '__ALL__', is_ads) AS is_ads
    ,if(platform IS NULL, '__ALL__', platform) AS platform
    ,if(target_type IS NULL, '__ALL__', target_type) AS target_type
    ,scenario_tag
    ,exp_sum(b.exp_group_ids, a.metrics) as exp_metrics
FROM
    map_data_${grass_region_without_quote} a
    JOIN user_exp_${grass_region_without_quote} b
    ON a.user_id = b.user_id
GROUP BY
    1,2,3,4,5;

--sql_divide_splitter--

CREATE TEMPORARY VIEW metric_table_${grass_region_without_quote} AS
SELECT
    feature_detail
    ,is_ads
    ,platform
    ,target_type
    ,scenario_tag
    ,exp_info.exp_group_id as exp_group_id
    ,cast(exp_info.fields[0] as bigint) as imp_uu
    ,cast(exp_info.fields[1] as bigint) as click_uu
    ,cast(exp_info.fields[2] as bigint) as ppv_uu
    ,cast(exp_info.fields[3] as bigint) as cart_uu
    ,cast(exp_info.fields[4] as bigint) as order_uu
    ,cast(exp_info.fields[5] as bigint) as item_imp_uu
    ,cast(exp_info.fields[6] as bigint) as item_click_uu
    ,cast(exp_info.fields[7] as bigint) as imp_cnt
    ,cast(exp_info.fields[8] as bigint) as click_cnt
    ,cast(exp_info.fields[9] as bigint) as ppv_cnt
    ,cast(exp_info.fields[10] as bigint) as cart_cnt
    ,exp_info.fields[11] as order_cnt
    ,cast (exp_info.fields[12] as bigint) as ppv_cnt_exclude_isback
    ,cast (exp_info.fields[13] as bigint) as item_imp_cnt
    ,cast (exp_info.fields[14] as bigint) as item_click_cnt
    ,exp_info.fields[15] as gmv
    ,exp_info.fields[16] as atc_same_day_order_cnt
    ,exp_info.fields[17] as atc_within_3day_order_cnt
    ,exp_info.fields[18] as atc_same_day_gmv
    ,exp_info.fields[19] as atc_within_3day_gmv
    ,exp_info.fields[20] as pc2_gmv
    ,cast (exp_info.fields[21] as bigint) as omni_imp_cnt
    ,cast (exp_info.fields[22] as bigint) as omni_click_cnt
    ,exp_info.fields[23] as squared_imp_cnt
    ,exp_info.fields[24] as squared_click_cnt
    ,exp_info.fields[25] as squared_order_cnt
    ,exp_info.fields[26] as squared_ppv_cnt_exclude_isback
from
    explode_metric_table_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(exp_metrics) as exp_info;

