create temporary view benchmark_w_cube_ads_load_temp_${grass_region_without_quote} as
    select *
    ,sum(case when is_ads = 'true' then imp_cnt else 0 end) over (partition by feature_detail, scenario_tag, exp_group_id, platform, target_type) as ads_imp_cnt
    ,sum(case when is_ads = '__ALL__' then imp_cnt else 0 end) over (partition by feature_detail, scenario_tag, exp_group_id, platform, target_type) as all_imp_cnt
    from metric_table_${grass_region_without_quote};

--sql_divide_splitter--

create temporary view res_${grass_region_without_quote} as
   select *,
          case when is_ads = 'true' then 1
               when is_ads = 'false' then 0
               when is_ads = '__ALL__' then ads_imp_cnt/all_imp_cnt
          end as ads_load
   from benchmark_w_cube_ads_load_temp_${grass_region_without_quote};

--sql_divide_splitter--

INSERT OVERWRITE TABLE srdi_mart.dws_sr_data_warehouse_platform_exp_base_metrics_1d
PARTITION (grass_region = ${grass_region}, local_date = ${local_date}, exp_type = 'assign_log_join')
SELECT
    platform
    ,is_ads
    ,feature_detail
    ,scenario_tag
    ,target_type
    ,exp_group_id
    ,imp_uu
    ,click_uu
    ,ppv_uu
    ,cart_uu
    ,order_uu
    ,item_imp_uu
    ,item_click_uu
    ,ads_load
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,ppv_cnt_exclude_isback
    ,cart_cnt
    ,order_cnt
    ,atc_same_day_order_cnt
    ,atc_within_3day_order_cnt
    ,item_imp_cnt
    ,item_click_cnt
    ,gmv
    ,atc_same_day_gmv AS atc_same_day_order_gmv
    ,atc_within_3day_gmv
    ,pc2_gmv

    ,imp_cnt AS imp_login_cnt
    ,item_imp_cnt AS item_imp_login_cnt
    ,click_cnt AS click_login_cnt
    ,item_click_cnt AS item_click_login_cnt
    ,ppv_cnt AS ppv_login_cnt
    ,cart_cnt AS cart_login_cnt
    ,order_cnt AS order_login_cnt
    ,ppv_cnt_exclude_isback AS ppv_exclude_isback_login_cnt
    ,gmv AS gmv_login
    ,atc_same_day_order_cnt AS atc_same_day_order_login_cnt
    ,atc_within_3day_order_cnt AS atc_within_3day_order_login_cnt
    ,atc_same_day_gmv AS atc_same_day_gmv_login
    ,atc_within_3day_gmv AS atc_within_3day_gmv_login
    ,pc2_gmv AS pc2_gmv_login

    ,omni_imp_cnt
    ,omni_click_cnt
    ,squared_imp_cnt
    ,squared_click_cnt
    ,squared_order_cnt
    ,squared_ppv_cnt_exclude_isback

FROM res_${grass_region_without_quote}

