    ,SUM(omni_click_cnt) AS omni_click_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(ppv_cnt_exclude_isback) AS ppv_cnt_exclude_isback
    ,SUM(item_imp_cnt) AS item_imp_cnt
    ,SUM(item_click_cnt) AS item_click_cnt
    ,SUM(gmv) AS gmv
    ,SUM(atc_same_day_order_cnt) AS atc_same_day_order_cnt
    ,SUM(atc_within_3day_order_cnt) AS atc_within_3day_order_cnt
    ,SUM(atc_same_day_gmv) AS atc_same_day_gmv
    ,SUM(atc_within_3day_gmv) AS atc_within_3day_gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM base_table_${grass_region_without_quote}
WHERE 
    nvl(source1_feature_detail, '') != '' 
    AND source1_feature_detail != feature_detail
    AND size(source1_scenario_tags) > 0
GROUP BY 1,2,3,4,5

UNION ALL
SELECT
    platform
    ,is_ads
    ,source2_feature_detail AS feature_detail
    ,user_id
    ,FILTER(source2_scenario_tags,
         value -> value like '%DA_%'
             or value in (
                 'dpm module Global Search business line Search'
                 ,'dpm reporting object you may also like module User Scenario business line Rcmd'
                 ,'dpm reporting object post purchase module User Scenario business line Rcmd'
                 ,'dpm module Daily Discover business line Homepage'
                 ,'dpm module Private Domin business line Rcmd'
             )
    ) AS scenario_tags
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(omni_imp_cnt) AS omni_imp_cnt
    ,SUM(omni_click_cnt) AS omni_click_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(ppv_cnt_exclude_isback) AS ppv_cnt_exclude_isback
    ,SUM(item_imp_cnt) AS item_imp_cnt
    ,SUM(item_click_cnt) AS item_click_cnt
    ,SUM(gmv) AS gmv
    ,SUM(atc_same_day_order_cnt) AS atc_same_day_order_cnt
    ,SUM(atc_within_3day_order_cnt) AS atc_within_3day_order_cnt
    ,SUM(atc_same_day_gmv) AS atc_same_day_gmv
    ,SUM(atc_within_3day_gmv) AS atc_within_3day_gmv
    ,SUM(pc2_gmv) AS pc2_gmv
FROM base_table_${grass_region_without_quote}
WHERE 
